/* ============================================================
   3. TIỆN ÍCH
   ============================================================ */
function tpl(str, data){
  return str.replace(/\{\{(\w+)\}\}/g, (m,k)=> (data[k]!==undefined? data[k] : ''));
}
function emptyMucdoCell(){ return {NB:0, TH:0, VD:0}; }
function rowTotal(r, kind){
  const c = r[kind];
  if(typeof c === 'number') return c; // dữ liệu cũ (trước khi có mức độ)
  if(!c) return 0;
  return (c.NB||0)+(c.TH||0)+(c.VD||0);
}
function migrateMatrixRows(){
  // chuyển dữ liệu ma trận cũ (số nguyên mỗi ô) sang dạng mới {NB,TH,VD}
  state.matrixRows.forEach(r=>{
    ['TN','DS','TLN','TL'].forEach(kind=>{
      if(typeof r[kind] === 'number'){
        r[kind] = {NB:0, TH:r[kind], VD:0}; // mặc định gán vào Thông hiểu, thầy chỉnh lại sau
      } else if(!r[kind]){
        r[kind] = emptyMucdoCell();
      }
    });
  });
}
function shuffleArray(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  return a;
}
function log(msg){
  const box = document.getElementById('logBox');
  if(!box) return;
  const t = new Date().toLocaleTimeString('vi-VN');
  box.textContent += `[${t}] ${msg}\n`;
  box.scrollTop = box.scrollHeight;
}
