    for(let j=Math.ceil(M.ymin); j<=Math.floor(M.ymax); j++){ svg += `<line x1="${X(M.xmin)}" y1="${Y(j)}" x2="${X(M.xmax)}" y2="${Y(j)}" stroke="currentColor" stroke-opacity=".12"/>`; if(j) html += lab(0, j, String(j), -10, 0); }
