  svg += `<line x1="${X(0)}" y1="${Y(M.ymin)}" x2="${X(0)}" y2="${Y(M.ymax)-10}" stroke="currentColor" marker-end="url(#${clipId}a)"/>`;
  html += lab(M.xmax, 0, 'x', 4, 11) + lab(0, M.ymax, 'y', -11, -6) + lab(0, 0, 'O', -9, 9);
  let inner = '';
  M.lines.forEach(l=>{
    if(l.t==='dung'){ inner += `<line x1="${X(l.x)}" y1="${Y(M.ymin)}" x2="${X(l.x)}" y2="${Y(M.ymax)}" stroke="currentColor" stroke-dasharray="4 3" stroke-width=".8"/>`; if(Math.abs(l.x)>1e-9) html += lab(l.x, 0, l.label, 9, M.ymin<-0.5?10:-10); }
    if(l.t==='ngang'){ inner += `<line x1="${X(M.xmin)}" y1="${Y(l.y)}" x2="${X(M.xmax)}" y2="${Y(l.y)}" stroke="currentColor" stroke-dasharray="4 3" stroke-width=".8"/>`; html += lab(0, l.y, l.label, M.xmin<-0.5?-10:10, -9); }
    if(l.t==='xien') inner += `<line x1="${X(M.xmin)}" y1="${Y(l.a*M.xmin+l.b)}" x2="${X(M.xmax)}" y2="${Y(l.a*M.xmax+l.b)}" stroke="currentColor" stroke-dasharray="4 3" stroke-width=".8"/>`;
  });
