  (hv.doc||[]).forEach(d=>{ inner += `<line x1="${X(d.x)}" y1="${Y(M.ymin)}" x2="${X(d.x)}" y2="${Y(M.ymax)}" stroke="currentColor" stroke-width="1.1"/>`; if(d.ten) html += lab(d.x, M.ymax - 0.12*(M.ymax - M.ymin), d.ten, 18, -6); });
