  M.segs.forEach(sg=>{ inner += `<polyline fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" points="${sg.map(p=> X(p[0]).toFixed(1)+','+Y(p[1]).toFixed(1)).join(' ')}"/>`; });
