  const xs = [0], ys = [0], ticksX = [], ticksY = [];
  const addT = (arr, val)=>{ if(Math.abs(val)>1e-9 && !arr.some(t=> Math.abs(t-val)<1e-9)) arr.push(val); };
  hv.bpt.forEach(e=>{
    if(e.a){ const xi = e.c/e.a; if(Math.abs(xi)<=12){ xs.push(xi); if(e.c) addT(ticksX, xi); } }
    if(e.b){ const yi = e.c/e.b; if(Math.abs(yi)<=12){ ys.push(yi); if(e.c) addT(ticksY, yi); } }
  });
  (hv.diem||[]).forEach(p=>{ xs.push(p[0]); ys.push(p[1]); addT(ticksX, p[0]); addT(ticksY, p[1]); });
  // giao điểm các bờ (hệ bất phương trình) cũng phải nằm trong khung
  hv.bpt.forEach((e,i)=> hv.bpt.slice(i+1).forEach(f=>{ const d = e.a*f.b - e.b*f.a; if(Math.abs(d)<1e-12) return; const x = (e.c*f.b - e.b*f.c)/d, y = (e.a*f.c - e.c*f.a)/d; if(Math.abs(x)<=12 && Math.abs(y)<=12){ xs.push(x); ys.push(y); } }));
  let xmin = Math.min(-2, ...xs) - 1, xmax = Math.max(2, ...xs) + 1, ymin = Math.min(-2, ...ys) - 1, ymax = Math.max(2, ...ys) + 1;
  if(hv.khung && [hv.khung.xmin,hv.khung.xmax,hv.khung.ymin,hv.khung.ymax].every(isFinite) && hv.khung.xmin<0 && hv.khung.xmax>0 && hv.khung.ymin<0 && hv.khung.ymax>0){
    ({xmin, xmax, ymin, ymax} = hv.khung);
  }
