  const sideX = t=>{ const e = hv.bpt.find(e=> e.a && e.b && Math.abs(e.c/e.a - t)<1e-9); if(!e) return 0; const xb = (e.c + 0.5*e.b)/e.a; return xb > t ? -1 : 1; };
  const sideY = t=>{ const e = hv.bpt.find(e=> e.a && e.b && Math.abs(e.c/e.b - t)<1e-9); if(!e) return 0; const yl = (e.c + 0.5*e.a)/e.b; return yl > t ? -1 : 1; };
