  o += `\\draw[->] (0,${f(M.ymin)})--(0,${f(M.ymax)}) node[below left,fill=white,inner sep=1pt]{$y$};\n`;
  o += `\\node[below left,fill=white,inner sep=1pt] at (0,0) {$O$};\n`;
