  M.ticksY.forEach(({v:t,s})=>{ o += `\\draw (0,${f(t)}) ++(2pt,0)--++(-4pt,0) node[${s<0?'below ':s>0?'above ':''}left,fill=white,inner sep=1pt]{$${mienNumT(t)}$};\n`; });
