const HINH_DANG = {
  chop:'Hình chóp', chop_cut:'Hình chóp cụt đều', lang_tru:'Hình lăng trụ', hop:'Hình hộp chữ nhật / lập phương', non:'Hình nón', tru:'Hình trụ', cau:'Mặt cầu, khối cầu',
  tam_giac:'Tam giác', do_dac:'Hình đo đạc thực tế (sông, hồ, tháp, tàu, núi…)', da_giac:'Đa giác phẳng (hình vuông, chữ nhật, thoi, bình hành, thang cân, lục giác đều, tam giác đều)', tron:'Đường tròn', tron_oxy:'Đường tròn trong hệ trục Oxy', elip:'Elip', hypebol:'Hypebol', parabol:'Parabol', doc:'Mặt phẳng nghiêng (mặt dốc) trên mặt phẳng ngang', phang:'Hình phẳng theo toạ độ (điểm, đoạn, vectơ)', oxy:'Hệ trục Oxy / lưới ô vuông có điểm, vectơ'};
