    const nm = String(hv.ten || (dang==='hop' ? "ABCD.A'B'C'D'" : "ABC.A'B'C'")).split('.'); let base = hinhNames(nm[0]), top = hinhNames(nm[1] || '');
    const day = dang==='hop' ? (hv.lap_phuong ? 'vuong' : 'chu_nhat') : (hv.day || (base.length === 3 ? 'tam_giac' : 'vuong'));
    let B = base.length === 3 && hinhDayTG(day, base, hv) ? hinhDayTG(day, base, hv) : hinhDay(day); B = B.slice(0, base.length);
    if(dang==='hop' && hv.lap_phuong) B = B.map(p=> [p[0]*0.85, p[1]*0.85, 0]);
    if(dang==='hop' && Array.isArray(hv.kich)) B = [[0,0,0], [hv.kich[0],0,0], [hv.kich[0],hv.kich[1],0], [0,hv.kich[1],0]];   // V2.37: đáy theo đúng tỉ lệ rộng, sâu
    if(top.length !== base.length) top = base.map(k=> k + "'");
