    ser.forEach((v, k)=>{ if(line){ const pts = v.map((y, i)=> [x0 + (i + 0.5)*slot, Y(y)]); P.push({t:'poly', pts, c:k}); pts.forEach((p, i)=>{ P.push({t:'dot', x:p[0], y:p[1], c:k}); if(hv.ghiSo) T(p[0], p[1] - 10*(k ? -1.3 : 1), bdNum(v[i]), {a:'middle'}); }); }
      else { const bw = slot*0.62/ns; v.forEach((y, i)=>{ const bx = x0 + i*slot + slot*0.19 + k*bw; Rct(bx, Y(y), bw, ya - Y(y), k, {stroke:true}); if(hv.ghiSo) T(bx + bw/2, Y(y) - 8, bdNum(y), {a:'middle'}); }); } });
