  if(shared){ D = JSON.parse(JSON.stringify(B, (k, v)=> /^ak_/.test(k) ? undefined : v)); const nk = sig + '|' + s + '|' + Date.now(); wsOpt.builds[nk] = D; wsOpt.sig[s] = nk; }
