wsOpt.figZ = (()=>{ try{ const v = +localStorage.getItem('mbp_wsFigZ'); return [60,70,80,90,100,110,120,130,140].includes(v) ? v : 100; }catch(e){ return 100; } })();   // V1.38: cỡ hình vẽ (%)
wsOpt.wakTL = (()=>{ try{ return localStorage.getItem('mbp_wakTL') === 'ngang' ? 'ngang' : 'dung'; }catch(e){ return 'dung'; } })();   // V1.32: trả lời ngắn trong khung xếp đứng (cột) / ngang (hàng)
