function wsJoinParts(it, S){ it.data.cauhoi = [S.intro, ...S.q.map((x, i)=> `${'abcdefgh'[i]}) ${x}`)].join('<br>'); it.data.loigiai = S.a.map((x, i)=> `${'abcdefgh'[i]}) ${x}`).join('<br>'); }
