function wsAllocateHand(maxParts, levels, kinds){
  const tl = [], n = maxParts.length; let nObj = 0, nDs = 0;
  kinds.forEach((k,i)=>{ if(k==='TL') tl.push(i); else if(k==='DS') nDs += maxParts[i]; else nObj++; });
  let best = null;
  for(const a of (nObj ? [2, 1] : [2])){ const rem = 40 - nObj*a - nDs; if(rem < 0) continue;
    if(!tl.length){ if(rem === 0) return {u:kinds.map(k=> k==='DS' ? 1 : a), p:maxParts.slice()}; continue; }
    // quy hoạch động trên tổng điểm: mỗi câu tự luận chọn số ý k (1..tối đa) và mức điểm mỗi ý v (2 = 0,5đ; 1 = 0,25đ; 4 = 1đ chỉ khi bắt buộc)
    let dp = new Map([[0, {c:0, ch:[]}]]);
    tl.forEach(i=>{ const m = maxParts[i], t = Math.min(m, levels[i]==='VD' || levels[i]==='VDC' ? 3 : 2), nx = new Map();
      dp.forEach((b, s0)=>{ for(let k = 1; k <= m; k++) for(const v of [2, 1, 4]){ const s1 = s0 + k*v; if(s1 > rem) continue;
        const c = b.c + (v===1 ? 1.2 : v===4 ? 9 : 0) + 1.5*(k - t)*(k - t) + (k===1 && m > 1 ? 1 : 0);
        const o = nx.get(s1); if(!o || c < o.c) nx.set(s1, {c, ch:b.ch.concat([[k, v]])}); } });
      dp = nx; });
    const r = dp.get(rem); if(!r) continue; const c = r.c + (a===1 ? 4 : 0);
    if(!best || c < best.c){ let j = 0; const u = [], p = []; kinds.forEach((k,i)=>{ if(k==='TL'){ const [kk, v] = r.ch[j++]; u.push(v); p.push(kk); } else { u.push(k==='DS' ? 1 : a); p.push(maxParts[i]); } }); best = {c, u, p}; } }
  return best ? {u:best.u, p:best.p} : null;
}
