  const gan = (q, a, b)=>{ const d = [b[0] - a[0], b[1] - a[1]], t = Math.max(0, Math.min(1, ((q[0] - a[0])*d[0] + (q[1] - a[1])*d[1])/(d[0]*d[0] + d[1]*d[1]))); return Math.hypot(q[0] - a[0] - t*d[0], q[1] - a[1] - t*d[1]); };
