// ---------- Bài: Các số đặc trưng đo mức độ phân tán ----------
const c10Nice = R=>{ // mẫu số liệu có trung bình nguyên, phương sai là số hữu tỉ đẹp
  for(let t=0;t<300;t++){
    const n = R.pick([5,6,8]), m = R.int(5,20);
    const dev = Array.from({length:n-1}, ()=> R.int(-5,5)); const last = -dev.reduce((a,b)=>a+b,0);
    if(Math.abs(last) > 6) continue;
    const data = [...dev, last].map(d=> m+d);
    const v = c10Var(data);
    if(Math.abs(v*4 - Math.round(v*4)) < 1e-9 && v>0) return R.shuffle(data);
  }
  return null;
};
