// ======================= LỚP 12 — KHOẢNG CÁCH TRONG Oxyz (CHO BẰNG PHƯƠNG TRÌNH) =======================
const QD = [[1, 2, 2, 3], [2, 1, 2, 3], [2, 2, 1, 3], [1, 4, 8, 9], [2, 3, 6, 7], [3, 2, 6, 7], [6, 2, 3, 7], [4, 4, 7, 9], [2, 6, 9, 11], [1, 0, 0, 1], [0, 3, 4, 5], [3, 0, 4, 5]];
const nrm = R=>{ const [p, q, r, L] = R.pick(QD), s = R.shuffle([p, q, r]).map(x=> x*R.sign()); return [s, L]; };
const lnT = (P0, u)=> `\\dfrac{x ${P0[0] < 0 ? '+' : '-'} ${Math.abs(P0[0])}}{${u[0]}} = \\dfrac{y ${P0[1] < 0 ? '+' : '-'} ${Math.abs(P0[1])}}{${u[1]}} = \\dfrac{z ${P0[2] < 0 ? '+' : '-'} ${Math.abs(P0[2])}}{${u[2]}}`.replace(/x - 0/g, 'x').replace(/y - 0/g, 'y').replace(/z - 0/g, 'z');
const plT = (n, d)=> termsT([[n[0], 'x'], [n[1], 'y'], [n[2], 'z'], [d, '']]) + ' = 0';
G(12,5,0,'TH','Oxyz: khoảng cách giữa đường thẳng và mặt phẳng song song', R=>{
  for(let g = 0; g < 60; g++){ const [n, L] = nrm(R), u = [R.int(-3, 3), R.int(-3, 3), R.int(-3, 3)]; if(hk_dot(u, n) !== 0 || u.some(x=> !x)) continue;
    const P0 = [R.int(-4, 4), R.int(-4, 4), R.int(-4, 4)], k = R.nz(-4, 4), d = k*L - hk_dot(n, P0);   // n·P0 + d = k·L
    const ans = T0(Math.abs(k)), wrong = pk(ans, [T0(Math.abs(k)*L), fr(Math.abs(k), L), T0(Math.abs(k) + 1), T0(Math.abs(d))].map(o=> Object.assign(o, {v:o.v}))); if(!wrong) continue;
    return {stem:`Trong không gian $Oxyz$, cho đường thẳng $\\Delta: ${lnT(P0, u)}$ và mặt phẳng $(P): ${plT(n, d)}$. Khoảng cách giữa $\\Delta$ và $(P)$ bằng`, ans, wrong,
      lg:`$\\vec u = (${u.join('; ')})$, $\\vec n = (${n.join('; ')})$, $\\vec u\\cdot\\vec n = 0$ và điểm $M_0${ptT(...P0)} \\in \\Delta$ không thuộc $(P)$ nên $\\Delta \\parallel (P)$. Do đó $d(\\Delta, (P)) = d(M_0, (P)) = \\dfrac{|${hk_dot(n, P0) + d}|}{${L}} = ${Math.abs(k)}$.`,
      verify:()=> hk_dot(u, n) === 0 && near(Math.abs(hk_dot(n, P0) + d)/hk_len(n), Math.abs(k), 1e-12)}; }
  return null;
});
