// ======================= TƯ DUY =======================
GT(6,3,0,'VD','Tư duy: đếm số nguyên x để phân số x/M nằm giữa hai phân số cho trước (quy đồng mẫu)', R=>{
  for(let g = 0; g < 60; g++){ const P = pickFs(R, 2, 60, [2, 3, 4, 5, 6, 8, 9, 10, 12]); if(!P) continue; let {fs:[[a, b], [c, d]], M} = P; if(a/b > c/d) [a, b, c, d] = [c, d, a, b]; const K = R.pick([1, 1, 2]), MM = M*K, lo = a*MM/b, hi = c*MM/d;
    const xs = []; for(let x = lo + 1; x < hi; x++) xs.push(x); if(xs.length < 2 || xs.length > 25) continue; const ask = R.pick(['cnt', 'sum']), val = ask === 'cnt' ? xs.length : xs.reduce((s, x)=> s + x, 0);
    return {stem:`${ask === 'cnt' ? 'Có bao nhiêu' : 'Tính tổng các'} số nguyên $x$ thoả mãn $${F(a, b)} < \\dfrac{x}{${MM}} < ${F(c, d)}$${ask === 'cnt' ? '?' : '.'}`, ans:val,
      lg:`Quy đồng mẫu với mẫu chung $${MM}$: $${F(a, b)} = ${F(lo, MM)}$, $${F(c, d)} = ${F(hi, MM)}$.<br>Khi đó $${F(lo, MM)} < \\dfrac{x}{${MM}} < ${F(hi, MM)} \\Leftrightarrow ${lo} < x < ${hi}$, nên $x \\in \\{${xs.join('; ')}\\}$.<br>${ask === 'cnt' ? `Có $${val}$ số nguyên $x$.` : `Tổng: $${val}$.`}`,
      verify:()=>{ let c2 = 0, s = 0; for(let x = -300; x <= 300; x++) if(a*MM < x*b && x*d < c*MM){ c2++; s += x; } return (ask === 'cnt' ? c2 : s) === val; }}; }
  return null;
});
GT(6,3,0,'VD','Tư duy: tìm phân số bằng phân số cho trước, biết tổng (hiệu) của tử và mẫu', R=>{
  for(let g = 0; g < 60; g++){ const [a, b] = q6Pick(R, [3, 4, 5, 7, 8, 9, 11]); if(a <= 0 || a >= b) continue; const k = R.int(2, 12), mode = R.pick(['sum', 'diff']), S = mode === 'sum' ? k*(a + b) : k*(b - a), ask = R.pick(['num', 'den']), val = ask === 'num' ? k*a : k*b;
    return {stem:`Tìm phân số bằng phân số ${FM(a, b)}, biết ${mode === 'sum' ? 'tổng của tử số và mẫu số' : 'hiệu của mẫu số và tử số'} của nó bằng $${S}$. ${ask === 'num' ? 'Tử số của phân số cần tìm là bao nhiêu?' : 'Mẫu số của phân số cần tìm là bao nhiêu?'}`, ans:val,
      lg:`Phân số cần tìm có dạng $\\dfrac{${a}k}{${b}k}$ (với $k$ là số nguyên khác $0$), vì nó bằng ${FM(a, b)} (phân số tối giản).<br>${mode === 'sum' ? `Tổng tử và mẫu: $${a}k + ${b}k = ${a + b}k = ${S}$` : `Hiệu mẫu và tử: $${b}k - ${a}k = ${b - a}k = ${S}$`} $\\Rightarrow k = ${k}$.<br>Phân số cần tìm là ${FM(k*a, k*b)}; ${ask === 'num' ? `tử số bằng $${val}$` : `mẫu số bằng $${val}$`}.`,
      verify:()=>{ const n = k*a, d = k*b; return n*b === a*d && (mode === 'sum' ? n + d : d - n) === S && (ask === 'num' ? n : d) === val; }}; }
  return null;
});
GT(6,3,0,'VD','Tư duy: thêm cùng một số vào tử và mẫu (hoặc chỉ vào tử) để được phân số mới cho trước', R=>{
  for(let g = 0; g < 80; g++){ const b = R.int(5, 30), a = R.int(1, b - 1), n = R.int(1, 20), both = R.rnd() < 0.6, [c, d] = both ? red(a + n, b + n) : red(a + n, b); if(d === (both ? b + n : b) && R.rnd() < 0.85) continue; if(gcdI(a, b) !== 1 || d < 2 || c >= d) continue;
    if(both){ if(d - c === 0) continue; const chk = (c*b - a*d)/(d - c); if(chk !== n) continue;
      return {stem:`Phải cộng cùng một số tự nhiên $n$ vào cả tử và mẫu của phân số ${FM(a, b)} để được phân số bằng ${FM(c, d)}. Tìm $n$.`, ans:n,
        lg:`Ta có $\\dfrac{${a} + n}{${b} + n} = ${F(c, d)}$.<br>Cách 1: hiệu của mẫu và tử không đổi khi cộng cùng một số: $(${b} + n) - (${a} + n) = ${b - a}$. Phân số mới bằng ${FM(c, d)}, mà hiệu mẫu – tử của ${FM(c, d)} là $${d - c}$, nên phân số mới là $${F(c, '' + d)} = ${F(c*(b - a)/(d - c), d*(b - a)/(d - c))}$ (nhân cả tử và mẫu với $${(b - a)/(d - c)}$).<br>Suy ra $${a} + n = ${c*(b - a)/(d - c)}$, tức $n = ${n}$.`,
        verify:()=> (a + n)*d === c*(b + n) && Number.isInteger((b - a)/(d - c))}; }
    if(!Number.isInteger(b/d)) continue;
    return {stem:`Phải cộng vào tử số của phân số ${FM(a, b)} số tự nhiên $n$ nào (giữ nguyên mẫu số) để được phân số bằng ${FM(c, d)}?`, ans:n,
      lg:`Quy đồng: ${FM(c, d)} $= ${F(c*b/d, b)}$ (nhân cả tử và mẫu với $${b/d}$).<br>Vậy $${a} + n = ${c*b/d}$, suy ra $n = ${n}$.`,
      verify:()=> (a + n)*d === c*b}; }
  return null;
});
G(6,3,0,'VD','Tư duy: so sánh phân số không cần quy đồng mẫu — quy đồng tử số, so sánh phần bù với 1, so sánh qua phân số trung gian', R=>{
  for(let g = 0; g < 80; g++){
    const mk = (kind)=>{ for(let t = 0; t < 40; t++){
      if(kind === 'tu'){ const p = R.int(2, 8), q = R.int(p + 1, 12), L = lcm(p, q), b = R.int(p + 2, p + 14), d = Math.round(b*q/p) + R.pick([-1, 1]); const A = [p, b], B = [q, d]; if(d <= q || gcdI(p, b) !== 1 || gcdI(q, d) !== 1 || p*d === q*b || L > 60) continue;
        return {A, B, how:`Quy đồng tử số: ${FM(...A)} $= ${F(L, b*L/p)}$, ${FM(...B)} $= ${F(L, d*L/q)}$; cùng tử, mẫu nào lớn hơn thì phân số nhỏ hơn`}; }
      if(kind === 'bu'){ const b = R.int(20, 2030), d = b + R.int(1, 30), A = [b - 1, b], B = [d - 1, d]; return {A, B, how:`So sánh phần bù với $1$: $1 - ${F(...A)} = ${F(1, b)}$, $1 - ${F(...B)} = ${F(1, d)}$; phần bù nhỏ hơn thì phân số lớn hơn`}; }
      const a = R.int(2, 40), b = 2*a + R.int(1, 9), c = R.int(2, 40), d = 2*c - R.int(1, 9); if(d <= c || gcdI(a, b) !== 1 || gcdI(c, d) !== 1) continue;   // a/b < 1/2 < c/d
      return {A:[a, b], B:[c, d], how:`So sánh qua phân số trung gian $\\dfrac{1}{2}$: ${FM(a, b)} $< \\dfrac{1}{2}$ (vì $2\\cdot ${a} < ${b}$), ${FM(c, d)} $> \\dfrac{1}{2}$ (vì $2\\cdot ${c} > ${d}$)`}; } return null; };
    const P = [mk('tu'), mk('bu'), mk('tg'), mk(R.pick(['tu', 'bu', 'tg']))]; if(P.some(x=> !x)) continue;
    const st = (p, ok)=>{ const lt = p.A[0]*p.B[1] < p.B[0]*p.A[1], s = ok === lt ? '<' : '>'; return `$${F(...p.A)} ${s} ${F(...p.B)}$`; }, w = R.int(0, 3);
    const opts = P.map((p, i)=> ({t:st(p, i === w), v:i}));
    return {stem:'Khẳng định nào sau đây là <b>đúng</b>?', ans:opts[w], wrong:opts.filter((_, i)=> i !== w),
      lg:P.map((p, i)=> `${'ABCD'[i] ? '' : ''}• ${p.how}, nên $${F(...p.A)} ${p.A[0]*p.B[1] < p.B[0]*p.A[1] ? '<' : '>'} ${F(...p.B)}$.`).join('<br>') + `<br>Vậy khẳng định đúng là ${opts[w].t}.`,
      verify:()=> P.every((p, i)=>{ const lt = p.A[0]*p.B[1] < p.B[0]*p.A[1], shown = opts[i].t.includes(' < '); return (i === w) === (shown === lt); }) && P.every(p=> p.A[0]*p.B[1] !== p.B[0]*p.A[1])}; }
  return null;
});
GE(6,3,0,'VD','Tư duy (tự luận): hỏi ngược với quy đồng — tìm phân số ban đầu, tìm x, tìm phân số thoả điều kiện', R=>{
  for(let g = 0; g < 60; g++){ const P = pickFs(R, 2, 90); if(!P) continue; const {fs:[[a, b], [c, d]], M} = P; if(M === b || M === d) continue; const N1 = a*M/b, N2 = c*M/d;
    let [p, q] = q6Pick(R, [3, 4, 5, 7]); p = Math.abs(p); if(p >= q) continue; const k = R.int(3, 9), S = k*(p + q);
    const Q = pickFs(R, 2, 40, [2, 3, 4, 5, 6, 8, 10, 12]); if(!Q) continue; let [[u, v], [s, t]] = Q.fs; if(u/v > s/t) [u, v, s, t] = [s, t, u, v]; const MM = Q.M, lo = u*MM/v, hi = s*MM/t, xs = []; for(let x = lo + 1; x < hi; x++) xs.push(x); if(xs.length < 2 || xs.length > 15) continue;
    return s6Parts('Giải các bài toán sau:', [
      {q:`Hai phân số tối giản (mẫu dương) sau khi quy đồng mẫu với mẫu số chung nhỏ nhất thì được ${FM(N1, M)} và ${FM(N2, M)}. Tìm hai phân số ban đầu.`, a:`Quy đồng không làm thay đổi giá trị phân số. Rút gọn: $${F(N1, M)} = ${F(a, b)}$; $${F(N2, M)} = ${F(c, d)}$. Kiểm tra BCNN$(${b}, ${d}) = ${M}$ đúng là mẫu chung nhỏ nhất. Hai phân số ban đầu là ${FM(a, b)} và ${FM(c, d)}.`,
        chk:()=>{ const [x1, y1] = red(N1, M), [x2, y2] = red(N2, M); return x1 === a && y1 === b && x2 === c && y2 === d && isLcm([b, d], M); }},
      {q:`Tìm phân số bằng phân số ${FM(p, q)}, biết tổng của tử số và mẫu số của nó bằng $${S}$.`, a:`Phân số cần tìm có dạng $\\dfrac{${p}k}{${q}k}$. Ta có $${p}k + ${q}k = ${p + q}k = ${S}$ nên $k = ${k}$. Phân số cần tìm là ${FM(p*k, q*k)}.`, chk:()=> p*k + q*k === S && (p*k)*q === p*(q*k)},
      {q:`Tìm các số nguyên $x$ sao cho $${F(u, v)} < \\dfrac{x}{${MM}} < ${F(s, t)}$.`, a:`Quy đồng mẫu: $${F(u, v)} = ${F(lo, MM)}$, $${F(s, t)} = ${F(hi, MM)}$. Do đó $${lo} < x < ${hi}$, $x \\in \\{${xs.join('; ')}\\}$.`,
        chk:()=>{ const f = []; for(let x = -200; x <= 200; x++) if(u*MM < x*v && x*t < s*MM) f.push(x); return f.length === xs.length && f.every((x, i)=> x === xs[i]); }}]); }
  return null;
});

Object.keys(GEN).filter(k=> !QD0.has(k)).forEach(k=>{ GEN[k].qd = 'V21.2'; });
