    const w2 = {t:`$y = \\dfrac{${termsT([[s > 0 ? 2 : -2, 'x'], [1, '']])}}{x ${d < 0 ? '+' : '-'} ${Math.abs(d) || 1}}`.replace('{x - 0}', '{x}') + '$', v:'w2'};   // phân thức: không xác định trên ℝ
    const w3 = {t:`$y = ${polyT([s, 0, 2*s, 0, 1])}$`, v:'w3'}, w4 = {t:`$y = ${polyT([-s, b, -C, d])}$`, v:'w4'};   // trùng phương; bậc ba ngược chiều
    const wrong = R.shuffle([w1, w2, w3, w4]).slice(0, 3);
