const nhPick3 = (ans, cand, R)=>{ const seen = new Set([ans.v]), w = []; (R ? R.shuffle(cand) : cand).forEach(c=>{ if(!seen.has(c.v) && w.length < 3){ seen.add(c.v); w.push(c); } }); return w.length < 3 ? null : w; };
