  const n = [(2*a + 1)*(2*b + 1)*(2*c + 1), 0, 0][0], dd = (()=>{ const e = v=> v % 2 === 0 ? v + 1 : v, o = v=> v % 2 === 0 ? v : v + 1; const E1 = e(a), O1 = o(a), E2 = e(b), O2 = o(b), E3 = e(c), O3 = o(c); return E1*E2*E3 + E1*O2*O3 + O1*E2*O3 + O1*O2*E3; })();
