const vnL = len=>{ const ng = vnNg(len), ans = vnR(len); return {ans, ng, lam:ng ? '' : ' (làm tròn đến hàng phần mười)', dv:ng ? '' : ', làm tròn đến hàng phần mười', eq:ng ? '=' : '\\approx'}; };
