GT(12,2,0,'VD','Ước lượng số số liệu không nhỏ hơn một giá trị c, coi số liệu rải đều trong mỗi nhóm', R=>{
  const g = pgTao(R), i = R.int(1, 3), c = g.lo(i) + g.w(i)*R.pick([0.25, 0.5, 0.75]), v = g.n - pgF(g, c), r = Math.round(v); if(Math.abs(v - r) > 0.45 && Math.abs(Math.abs(v - r) - 0.5) < 0.04) return null;
  const o = {stem:`${pgDe(g)} Coi các số liệu rải đều trong mỗi nhóm, hãy ước lượng số số liệu không nhỏ hơn $${nt(c)}$ (làm tròn đến hàng đơn vị).`, ans:r, lg:`Trong nhóm $${g.grp(i)}$, phần từ $${nt(c)}$ trở lên chiếm tỉ lệ $${pgN2((g.hi(i) - c)/g.w(i))}$ của nhóm, ứng với khoảng $${pgN2(g.f[i]*(g.hi(i) - c)/g.w(i))}$ số liệu.<br>Cộng với tần số các nhóm sau: $${pgS(g.f.slice(i + 1))}$. Tổng khoảng $${pgN2(v)}$, làm tròn được $${r}$.`, verify:()=>{ let s = 0; for(let j = 0; j < g.k; j++){ const a = Math.max(g.lo(j), c); if(a < g.hi(j)) s += g.f[j]*(g.hi(j) - a)/g.w(j); } return Math.round(s) === o.ans; }};
  return r ? o : null;
});

