  const ans = ngOp(T, pt), wrong = ngW(R, ans, [ngOp(ngPr([[k, ngC1], [s*k, ngS1]]), pt), ngOp([[k, ngC1], [-s*k, ngS1]], pt), ngOp([[qm(k, -1), ngS1], [s*k, ngC1]], pt), ngOp([[k, ngS1], [k, ngC1], [k, ngX(1)]], pt)]); if(!wrong) return null;
