  const G = e8G(V[Y], V[Z], V[W]), M = e8Mid(V[X0], G), N = e8Mid(V[Z], V[W]), Xp = e8Cut(V[Y], M, e8Nor(V[X0], V[Z], V[W]), V[X0]), sc = 5*j/e8Dist(V[X0], N);
