  const L = R.pick([4, 4.8, 5, 6, 7.2, 8, 9, 10]), H = R.int(30, 70), x = R.pick([1, 1.2, 1.5, 2, 2.4, 2.5, 3, 3.6, 4, 4.5, 5]), y = H*x/L; if(x >= L - 0.4 || !tlF(y) || H/(L*100) > 1/8 || H/(L*100) < 1/16) return null;
