  pts.L0 = [-(a + step*0.6)/2, -16.8]; pts.R0 = [(a + step*0.6)/2, -16.8]; pts.LT = [-(b - step*0.6)/2, (n - 1)*28 + 16.8]; pts.RT = [(b - step*0.6)/2, (n - 1)*28 + 16.8]; seg.push(['L0', 'LT'], ['R0', 'RT']);
  const an = Object.keys(pts);
