  const n = R.pick([6, 8, 10, 12, 14, 15, 16, 18, 20, 21, 22, 24, 26, 27, 28, 30, 32, 33, 34, 35, 36, 39, 40, 42])*R.sign(), A = Math.abs(n), ds = []; for(let d = 1; d*d <= A; d++) if(A % d === 0) ds.push(d);
  const pairs = [], seen = new Set(); ds.forEach(d=> [[d, n/d], [-d, -n/d]].forEach(q=>{ const key = q.slice().sort((u, v)=> u - v).join(','); if(!seen.has(key)){ seen.add(key); pairs.push(q); } }));   // V1.88: −16 = 4·(−4) = (−4)·4 chỉ tính một cách
