  keys.forEach(k=>{ const g = G[k]; by[g.grade] = (by[g.grade] || 0) + 1; });
  if(!keys.length){ alert('Chưa có dạng nào được duyệt. Duyệt các dạng ở mục Câu hỏi thay số / Câu hỏi cố định trước.'); return; }
  const pack = {app:'IMs', v:1, at:new Date().toISOString(), from:'MathBank ' + APP_VERSION, genVersion:GENLIB.GEN_VERSION, keys:keys.sort()};
  download('ims_pack.json', JSON.stringify(pack));
