  nI.forEach((k, i)=>{ const c = Math.floor(i/R), r = i % R; P[k] = {x:WAK.x0 + c*WAK.colW + WAK.bx, y:WAK.y0 + r*WAK.pitchY}; BP[k] = WAK.bp; });
  const v2 = +v >= 2, per = v2 ? 3 : 2, cw = v2 ? WAK.tColW2 : WAK.tColW, blk = v2 ? WAK.tBlk2 : WAK.tBlk, tbx = v2 ? WAK.tBx2 : 4 + WAK.bx, tbp = v2 ? WAK.tBp2 : WAK.bp;
