  const html = '<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cài app chấm bài</title></head><body>' + T.innerHTML.replace('<!--QR-->', qrSvg('https://chudinhcoi-afk.github.io/cham-bai/', 170)) + '</body></html>';
