  if(id >= AK_MIN && (t.up || state.mbpPaired)){ const n = await mbpCloudPut(ids.filter(i=> i >= AK_MIN)); msg += n ? ' Điện thoại đã liên kết tự nhận thang điểm mới.' : ' Chưa gửi được lên máy chủ (kiểm tra mạng) — điện thoại dùng mã QR mới.'; }
