    D.rect.forEach(([x, y, w, h])=>{ ln(x, y, x + w, y, 0.3); ln(x, y + h, x + w, y + h, 0.3); ln(x, y, x, y + h, 0.3); ln(x + w, y, x + w, y + h, 0.3); });
