    pass:[['🙂', 'Em đã đạt yêu cầu, nhưng còn hổng một số phần của bài.'], ['🙂', 'Em qua mức trung bình, các câu sai dưới đây cần xem lại ngay.']],
    grow:[['📌', 'Chưa đạt trung bình — em cần cố gắng nhiều hơn nữa.'], ['📌', 'Em làm được một phần, nhưng như vậy là chưa đủ: cần chắc hơn ở các câu cơ bản.']],
    low:[['⚠️', 'Kết quả này chưa đạt — và thầy cô biết đây chưa phải sức của em.'], ['📉', 'Điểm lần này đáng báo động, em cần nghiêm túc nhìn lại cách học bài này.'], ['⏰', 'Em đang bị bỏ lại khá xa so với yêu cầu của bài — đã đến lúc phải tăng tốc.']],
