  const wrap = s=>{ const out = []; let cur = ''; String(s).split(' ').forEach(w=>{ const x = cur ? cur + ' ' + w : w; if(t.measureText(x).width > maxW && cur){ out.push(cur); cur = w; } else cur = x; }); if(cur) out.push(cur); return out; };
  const B = cm.lines.map(l=> ({l, rows:wrap(l.i + '  ' + l.t)})), hd = Math.round(fz*1.9), gap = Math.round(fz*0.5);
  const H = hd + B.reduce((s, b)=> s + b.rows.length*lh + pad*1.3 + gap, 0) + pad;
  const c = document.createElement('canvas'); c.width = W; c.height = canvas.height + H; const x = c.getContext('2d');
  x.drawImage(canvas, 0, 0); const y0 = canvas.height; const g = x.createLinearGradient(0, y0, 0, y0 + H); g.addColorStop(0, '#fffaf0'); g.addColorStop(1, '#fdf1ff'); x.fillStyle = g; x.fillRect(0, y0, W, H);
  x.fillStyle = '#7a3e00'; x.font = `800 ${Math.round(fz*1.05)}px "Segoe UI", Roboto, Arial, sans-serif`; x.textBaseline = 'middle'; x.fillText('💬 Nhận xét của thầy cô', pad, y0 + hd/2 + 2);
  const rr = (X, Y, w, h, r, tl)=>{ x.beginPath(); x.moveTo(X + (tl ? 4 : r), Y); x.arcTo(X + w, Y, X + w, Y + h, r); x.arcTo(X + w, Y + h, X, Y + h, r); x.arcTo(X, Y + h, X, Y, r); x.arcTo(X, Y, X + w, Y, tl ? 4 : r); x.closePath(); };
  let y = y0 + hd;
