      const vt = a=> `<span class="calc-ex">(${a.map(t=>{ const ex = calcExactTex(t); return ex ? calcTexHtml(ex) : calcDec(t); }).join('; ')})</span>`;
      const dot = u.reduce((s,t,i)=> s + t*v[i], 0), len = a=> Math.sqrt(a.reduce((s,t)=> s + t*t, 0)), lu = len(u), lv = len(v);
