      if(u.length===3){ const cr = [u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0]]; h += row('[u, v] =', vt(cr)); if(cr.every(t=> Math.abs(t) < 1e-10)) h += row('', '<span class="calc-eq">u, v cùng phương</span>'); }
      else { const d = u[0]*v[1] - u[1]*v[0]; h += row('', `<span class="calc-eq">${Math.abs(d) < 1e-10 ? 'u, v cùng phương' : Math.abs(dot) < 1e-10 ? 'u ⊥ v' : 'u, v không cùng phương'}</span>`); }
      out.innerHTML = h;
